-- vif-tiers-intervenu-blesse — Le voisin s'est interposé et a pris un coup
SELECT public.fn_cp_import_case('vif-tiers-intervenu-blesse', '{"slug": "vif-tiers-intervenu-blesse", "title": "Le voisin s''est interposé et a pris un coup", "theme_slug": "violences-conjugales", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 22 heures. Vous êtes engagés dans une cage d''escalier suite à des violences conjugales entre M. et Mme PASCAL, un voisin du dessus, M. OLIVEIRA, s''étant interposé physiquement en entendant la scène et ayant reçu un coup de poing au visage pour son intervention. Vous vous retrouvez avec trois personnes à prendre en charge simultanément : le couple en crise et ce tiers blessé par sa propre intervention.\n\nM. OLIVEIRA, sonné mais conscient, saigne du nez et semble hésiter entre rester pour aider davantage et rentrer chez lui soigner sa blessure. Mme PASCAL, choquée, remercie ce voisin avec effusion tandis que M. PASCAL reste à l''écart, visiblement embarrassé par la situation qui a dégénéré au-delà du seul cadre conjugal.\n\nVous devez organiser la prise en charge de ces trois personnes sans que l''une d''elles ne soit négligée au profit des deux autres.", "questions": [{"position": 1, "max_points": 5, "label": "Comment organisez-vous la prise en charge simultanée de ces trois personnes ?", "hint": "Le tiers blessé ne doit pas devenir une préoccupation secondaire simplement parce que l''intervention initiale concernait le couple.", "perfect": "Je m''assure que M. OLIVEIRA, bien que non partie prenante initiale de la dispute conjugale, bénéficie d''une prise en charge aussi sérieuse que celle du couple, son intervention lui ayant valu une blessure qui mérite une attention immédiate.\n\nJe sollicite si possible l''appui d''un collègue pour que chaque personne puisse être prise en charge séparément, plutôt que de gérer les trois situations de front avec un seul effectif, ce qui risquerait de négliger l''une d''entre elles.\n\nJe évalue rapidement l''état de M. OLIVEIRA pour déterminer s''il nécessite des soins médicaux, un saignement de nez pouvant parfois masquer une blessure plus sérieuse qu''il n''y paraît au premier regard.\n\nJe ne laisse pas l''effusion de reconnaissance de Mme PASCAL envers son voisin détourner mon attention du fait que ce tiers reste une victime à part entière de cette soirée, avec ses propres besoins à traiter.", "points": [{"position": 1, "label": "Assurer une prise en charge du tiers aussi sérieuse que celle du couple", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ne pas négliger le tiers au profit du couple.", "groups": [{"position": 1, "keywords": ["prise en charge sérieuse", "tiers blessé", "aussi important que le couple"]}]}, {"position": 2, "label": "Solliciter l''appui d''un collègue pour une prise en charge séparée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter de gérer les trois situations de front avec un seul effectif.", "groups": [{"position": 1, "keywords": ["appui d''un collègue", "prise en charge séparée", "pas de front unique"]}]}, {"position": 3, "label": "Évaluer rapidement l''état du tiers pour déterminer un besoin de soins", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Un saignement de nez peut masquer une blessure plus sérieuse.", "groups": [{"position": 1, "keywords": ["évaluer l''état", "besoin de soins", "blessure masquée possible"]}]}, {"position": 4, "label": "Ne pas laisser l''effusion de reconnaissance détourner l''attention de ses besoins", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Le tiers reste une victime à part entière avec ses propres besoins.", "groups": [{"position": 1, "keywords": ["victime à part entière", "propres besoins", "ne pas détourner l''attention"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous le témoignage de M. OLIVEIRA tout en traitant sa propre plainte potentielle pour les coups reçus ?", "hint": "Ce voisin cumule deux statuts, celui de témoin des violences conjugales et celui de victime directe de coups reçus.", "perfect": "Je recueille son témoignage sur ce qu''il a vu et entendu de la dispute conjugale avant son intervention, ces éléments étant précieux pour objectiver la situation entre M. et Mme PASCAL au-delà de leurs seules déclarations respectives.\n\nJe l''informe clairement de son droit à déposer plainte pour les coups qu''il a lui-même reçus, ce qui constitue une démarche distincte de son rôle de témoin, sans que l''une n''exclue l''autre.\n\nJe ne minimise pas son geste d''intervention en le traitant comme une simple anecdote annexe, en reconnaissant le courage que représente le fait de s''interposer physiquement dans une dispute qui ne le concernait pas initialement.\n\nJe consigne séparément sa qualité de témoin des violences conjugales et sa qualité de victime des coups qu''il a reçus, ces deux aspects de son intervention méritant chacun d''être clairement documentés.", "points": [{"position": 1, "label": "Recueillir son témoignage sur la dispute conjugale observée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éléments précieux pour objectiver la situation du couple.", "groups": [{"position": 1, "keywords": ["témoignage sur la dispute", "objectiver", "précieux"]}]}, {"position": 2, "label": "L''informer clairement de son droit à déposer plainte pour les coups reçus", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Démarche distincte de son rôle de témoin, sans exclusion mutuelle.", "groups": [{"position": 1, "keywords": ["droit de plainte", "démarche distincte", "sans exclusion"]}]}, {"position": 3, "label": "Ne pas minimiser son geste d''intervention comme une anecdote", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Reconnaître le courage de s''interposer dans une dispute qui ne le concernait pas.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "courage reconnu", "pas une anecdote"]}]}, {"position": 4, "label": "Consigner séparément son statut de témoin et de victime", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Deux aspects distincts à documenter clairement.", "groups": [{"position": 1, "keywords": ["consigner séparément", "témoin et victime", "documenter clairement"]}]}]}, {"position": 3, "max_points": 5, "label": "M. OLIVEIRA hésite à déposer plainte, craignant de détériorer ses relations de voisinage futures avec le couple PASCAL. Comment l''accompagnez-vous dans cette décision ?", "hint": "Cette préoccupation de voisinage est légitime et mérite d''être entendue sans pour autant orienter sa décision dans un sens ou dans l''autre.", "perfect": "Je respecte son hésitation sans le pousser à déposer plainte contre son gré, cette décision devant rester la sienne face à sa propre appréciation de ses relations de voisinage futures.\n\nJe reconnais que sa préoccupation est légitime, vivre à proximité immédiate de personnes contre lesquelles on porterait plainte pouvant effectivement générer une gêne durable qu''il est seul à pouvoir évaluer pour lui-même.\n\nJe ne minimise pas pour autant les coups qu''il a reçus en l''encourageant à renoncer à ses droits, en lui présentant simplement les options qui s''offrent à lui sans orienter sa décision dans un sens ou dans l''autre.\n\nJe lui indique qu''il peut prendre le temps de réfléchir et revenir déposer plainte ultérieurement s''il le souhaite, cette porte restant ouverte sans qu''un délai particulier ne s''impose à lui pour se décider.", "points": [{"position": 1, "label": "Respecter son hésitation sans le pousser à déposer plainte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Décision qui lui appartient face à sa propre appréciation.", "groups": [{"position": 1, "keywords": ["respecter l''hésitation", "sans pousser", "sa décision"]}]}, {"position": 2, "label": "Reconnaître la légitimité de sa préoccupation de voisinage", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Gêne durable qu''il est seul à pouvoir évaluer pour lui-même.", "groups": [{"position": 1, "keywords": ["préoccupation légitime", "gêne durable", "lui seul peut évaluer"]}]}, {"position": 3, "label": "Ne pas minimiser les coups reçus en l''encourageant à renoncer", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Présenter les options sans orienter la décision.", "groups": [{"position": 1, "keywords": ["ne pas minimiser les coups", "présenter les options", "sans orienter"]}]}, {"position": 4, "label": "Indiquer qu''il peut revenir déposer plainte ultérieurement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Porte ouverte sans délai particulier imposé.", "groups": [{"position": 1, "keywords": ["revenir ultérieurement", "porte ouverte", "sans délai imposé"]}]}]}]}'::jsonb);

-- vif-suivi-apres-signalement-ecole — La directrice a déjà signalé deux fois, sans retour
SELECT public.fn_cp_import_case('vif-suivi-apres-signalement-ecole', '{"slug": "vif-suivi-apres-signalement-ecole", "title": "La directrice a déjà signalé deux fois, sans retour", "theme_slug": "violences-conjugales", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 8 h 45. Vous êtes reçu par la directrice d''une école élémentaire qui vous interpelle avec une certaine lassitude visible, expliquant avoir déjà signalé à deux reprises, au cours des derniers mois, des inquiétudes concernant un élève de 7 ans dont elle soupçonne qu''il est exposé à des violences conjugales à son domicile, sans avoir jamais reçu le moindre retour sur les suites données à ces signalements.\n\nElle précise que l''enfant présente à nouveau ce matin des signes de fatigue et d''anxiété inhabituels, et qu''elle hésite désormais à signaler une troisième fois, se demandant si cela sert réellement à quelque chose compte tenu du silence qu''elle a rencontré jusqu''à présent.\n\nElle ne vous reproche rien personnellement, n''ayant jamais eu affaire à vous auparavant, mais son découragement est palpable et pourrait, si rien ne change, la conduire à renoncer à signaler une prochaine fois si la situation venait à se reproduire.", "questions": [{"position": 1, "max_points": 5, "label": "Comment accueillez-vous ce découragement exprimé par un partenaire institutionnel habitué à signaler ?", "hint": "Un partenaire qui se décourage de signaler représente une perte d''information potentiellement grave pour l''avenir.", "perfect": "J''accueille son découragement avec sérieux, en comprenant que ce sentiment d''absence de retour, s''il perdure, pourrait la conduire à ne plus signaler à l''avenir, ce qui représenterait une perte d''information potentiellement grave pour la protection de cet enfant.\n\nJe ne minimise pas sa frustration en la traitant comme un simple ressenti personnel, en reconnaissant que l''absence de retour sur des signalements antérieurs est une réalité fréquente qui peut légitimement décourager les professionnels engagés dans ce type de démarche.\n\nJe reste attentive à valoriser sa vigilance et sa persévérance passées, sans qu''elle n''ait à se justifier de son hésitation actuelle, cette lassitude étant compréhensible plutôt qu''une faiblesse professionnelle de sa part.\n\nJe l''encourage à ne pas renoncer à signaler si la situation se reproduisait, tout en comprenant parfaitement les raisons de son découragement actuel face à ce silence institutionnel qu''elle a rencontré.", "points": [{"position": 1, "label": "Prendre au sérieux le risque qu''elle cesse de signaler à l''avenir", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : partenaire découragé par l''absence de suites visibles.", "groups": [{"position": 1, "keywords": ["risque de cesser de signaler", "perte d''information", "protection de l''enfant"]}]}, {"position": 2, "label": "Ne pas minimiser sa frustration comme un simple ressenti personnel", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "L''absence de retour est une réalité fréquente et légitimement décourageante.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "réalité fréquente", "légitimement décourageante"]}]}, {"position": 3, "label": "Valoriser sa vigilance et sa persévérance passées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Lassitude compréhensible, pas une faiblesse professionnelle.", "groups": [{"position": 1, "keywords": ["valoriser la vigilance", "persévérance", "pas une faiblesse"]}]}, {"position": 4, "label": "L''encourager à ne pas renoncer tout en comprenant son découragement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Équilibre entre encouragement et compréhension.", "groups": [{"position": 1, "keywords": ["encourager sans renoncer", "comprendre le découragement"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment répondez-vous à son besoin implicite de savoir ce qu''il est advenu de ses signalements précédents, tout en respectant le secret qui entoure ces procédures ?", "hint": "Restaurer la confiance ne signifie pas divulguer des éléments couverts par la confidentialité de la procédure.", "perfect": "Je ne lui divulgue aucun élément précis sur le contenu ou les suites de ses signalements précédents, cette information restant couverte par la confidentialité de la procédure et ne pouvant lui être communiquée telle quelle.\n\nJe lui explique de manière générale que l''absence de retour visible ne signifie pas nécessairement l''absence de suite donnée à ses signalements, ces démarches pouvant se poursuivre de manière invisible pour elle sans que cela signifie un classement sans suite.\n\nJe m''engage à transmettre ce nouveau signalement avec la même rigueur que les précédents, en y ajoutant les éléments d''aujourd''hui concernant la fatigue et l''anxiété observées chez l''enfant ce matin.\n\nJe reste honnête sur le fait que je ne peux pas lui garantir un retour d''information systématique à l''avenir, ce mécanisme de communication ne relevant pas entièrement de mon propre pouvoir, tout en comprenant que cette limite participe de sa frustration légitime.", "points": [{"position": 1, "label": "Ne pas divulguer d''éléments couverts par la confidentialité de la procédure", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : restaurer la confiance sans divulguer d''éléments couverts.", "groups": [{"position": 1, "keywords": ["ne pas divulguer", "confidentialité", "éléments couverts"]}]}, {"position": 2, "label": "Expliquer que l''absence de retour ne signifie pas l''absence de suite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Les démarches peuvent se poursuivre de manière invisible.", "groups": [{"position": 1, "keywords": ["absence de retour", "pas absence de suite", "invisible pour elle"]}]}, {"position": 3, "label": "S''engager à transmettre ce nouveau signalement avec la même rigueur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ajouter les éléments d''aujourd''hui aux précédents.", "groups": [{"position": 1, "keywords": ["même rigueur", "transmettre", "éléments d''aujourd''hui"]}]}, {"position": 4, "label": "Rester honnête sur l''impossibilité de garantir un retour systématique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Reconnaître les limites du mécanisme sans fausse promesse.", "groups": [{"position": 1, "keywords": ["honnêteté sur les limites", "pas de garantie", "reconnaître la frustration"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous concrètement ce troisième signalement pour qu''il bénéficie d''une attention particulière compte tenu de sa répétition ?", "hint": "Trois signalements pour le même enfant sur une période limitée constituent en eux-mêmes un faisceau qui mérite d''être mis en avant.", "perfect": "Je consulte, si possible, les deux signalements précédents pour comprendre leur contenu et la manière dont ils ont pu être traités, cette continuité étant importante pour bien situer ce troisième signalement dans son contexte.\n\nJe mets en avant, dans la transmission de ce signalement, le caractère répété de ces alertes concernant le même enfant, cette récurrence constituant un faisceau d''indices qui mérite une attention particulière plutôt qu''un traitement isolé.\n\nJe recueille avec précision les observations de ce matin sur la fatigue et l''anxiété de l''enfant, ces éléments récents venant s''ajouter à l''historique déjà constitué par les signalements précédents.\n\nJe consigne mon propre passage et cette conversation avec la directrice, ce qui permet de tracer explicitement le fait que cette professionnelle a exprimé un découragement, information qui pourrait elle-même être utile pour améliorer les mécanismes de retour à l''avenir.", "points": [{"position": 1, "label": "Consulter les deux signalements précédents pour comprendre le contexte", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Importante continuité pour bien situer ce troisième signalement.", "groups": [{"position": 1, "keywords": ["consulter les précédents", "comprendre le contexte", "continuité"]}]}, {"position": 2, "label": "Mettre en avant le caractère répété des alertes dans la transmission", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Faisceau d''indices méritant une attention particulière plutôt qu''un traitement isolé.", "groups": [{"position": 1, "keywords": ["caractère répété", "faisceau d''indices", "attention particulière"]}]}, {"position": 3, "label": "Recueillir précisément les observations de ce matin", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éléments récents s''ajoutant à l''historique déjà constitué.", "groups": [{"position": 1, "keywords": ["observations de ce matin", "s''ajouter à l''historique", "éléments récents"]}]}, {"position": 4, "label": "Consigner le découragement exprimé pour améliorer les mécanismes futurs", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information utile pour améliorer les retours à l''avenir.", "groups": [{"position": 1, "keywords": ["consigner le découragement", "améliorer les mécanismes", "utile pour l''avenir"]}]}]}]}'::jsonb);

-- vif-victime-alcoolisee-lors-des-faits — Il insiste sur le fait qu'elle avait bu
SELECT public.fn_cp_import_case('vif-victime-alcoolisee-lors-des-faits', '{"slug": "vif-victime-alcoolisee-lors-des-faits", "title": "Il insiste sur le fait qu''elle avait bu", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 3 heures. Vous êtes engagés au domicile de Mme FONTENELLE suite à des violences de son conjoint, qu''elle décrit avec un récit globalement cohérent malgré une légère alcoolisation manifeste de sa part. Elle présente des marques de coups récentes sur les bras et le visage.\n\nM. FONTENELLE, présent et évincé peu après votre arrivée, insiste à plusieurs reprises, avant son départ, sur le fait qu''elle « avait bu », comme si cette information devait à elle seule remettre en question la crédibilité de son récit ou minimiser la gravité de ce qui s''est produit. Il répète cette précision presque comme un argument de défense qu''il tient à faire valoir auprès de vous avant d''être évincé.\n\nMme FONTENELLE elle-même, entre deux larmes, semble par moments douter de sa propre parole, se demandant à voix haute si elle a « bien vu » ce qui s''est passé compte tenu de son état, comme si l''argument de son conjoint avait déjà commencé à l''atteindre.", "questions": [{"position": 1, "max_points": 5, "label": "Comment traitez-vous cette insistance de M. FONTENELLE sur l''état d''alcoolisation de sa compagne ?", "hint": "Cet argument, présenté comme une explication, fonctionne en réalité comme une tentative de décrédibilisation qu''il convient de reconnaître pour ce qu''elle est.", "perfect": "Je reconnais cette insistance pour ce qu''elle est réellement, à savoir une tentative de décrédibilisation de la parole de la victime plutôt qu''une information neutre qu''il chercherait simplement à porter à ma connaissance.\n\nJe ne laisse pas cet argument influencer mon appréciation des faits constatés, les marques de coups étant des éléments matériels objectifs qui existent indépendamment de l''état de consommation d''alcool de la victime au moment des faits.\n\nJe reste factuelle face à M. FONTENELLE, sans entrer dans un débat sur la pertinence de son argument, en me concentrant sur les constatations matérielles qui fondent mon intervention plutôt que sur cette tentative de relativisation.\n\nJe garde à l''esprit qu''un état d''alcoolisation, même réel, de la victime ne change en rien la qualification des violences qu''elle a subies, ce lien de causalité qu''il tente d''établir n''ayant aucune pertinence juridique sur la caractérisation des faits.", "points": [{"position": 1, "label": "Reconnaître cette insistance comme une tentative de décrédibilisation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ne pas laisser l''état de la victime relativiser les faits.", "groups": [{"position": 1, "keywords": ["tentative de décrédibilisation", "pas une information neutre", "reconnaître la stratégie"]}]}, {"position": 2, "label": "Ne pas laisser cet argument influencer l''appréciation des faits constatés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Les marques de coups sont des éléments objectifs indépendants de l''alcoolisation.", "groups": [{"position": 1, "keywords": ["ne pas influencer", "éléments objectifs", "indépendant de l''alcoolisation"]}]}, {"position": 3, "label": "Rester factuelle sans entrer dans un débat sur la pertinence de l''argument", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Se concentrer sur les constatations matérielles.", "groups": [{"position": 1, "keywords": ["rester factuelle", "sans débat", "constatations matérielles"]}]}, {"position": 4, "label": "Considérer que l''état d''alcoolisation ne change rien à la qualification des violences", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Aucune pertinence juridique sur la caractérisation des faits.", "groups": [{"position": 1, "keywords": ["ne change rien à la qualification", "aucune pertinence juridique"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment aidez-vous Mme FONTENELLE à ne pas douter de sa propre parole, elle-même influencée par l''argument de son conjoint ?", "hint": "L''argument de l''auteur peut avoir un effet direct sur la victime elle-même, qui commence à intérioriser ce doute jeté sur sa crédibilité.", "perfect": "Je la rassure explicitement sur le fait que son état de consommation d''alcool, même réel, ne remet en rien en cause la réalité des marques de coups que je constate moi-même sur elle, ces éléments matériels étant indépendants de sa propre perception de la soirée.\n\nJe l''aide à distinguer ce dont elle est certaine, notamment les blessures qu''elle ressent physiquement, de ce qui pourrait être plus flou dans son souvenir précis des circonstances exactes, sans que cette distinction ne remette en cause l''ensemble de son récit.\n\nJe ne la presse pas de reconstituer un récit parfaitement linéaire et détaillé si son état rend certains éléments moins précis, en recueillant ce qu''elle peut affirmer avec certitude sans exiger une exhaustivité qu''elle ne peut pas garantir.\n\nJe reste attentive à contrer, par mon attitude professionnelle et rassurante, l''effet que l''argument de son conjoint a pu commencer à produire sur sa propre confiance en sa perception des événements.", "points": [{"position": 1, "label": "La rassurer que son état n''invalide pas les constatations matérielles", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Marques de coups indépendantes de sa perception de la soirée.", "groups": [{"position": 1, "keywords": ["rassurer explicitement", "constatations indépendantes", "pas invalidé"]}]}, {"position": 2, "label": "L''aider à distinguer ce dont elle est certaine de ce qui est plus flou", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Distinction sans remettre en cause l''ensemble du récit.", "groups": [{"position": 1, "keywords": ["distinguer certitude et flou", "sans remettre en cause", "l''ensemble"]}]}, {"position": 3, "label": "Ne pas la presser de reconstituer un récit parfaitement linéaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Recueillir ce qu''elle peut affirmer sans exiger une exhaustivité impossible.", "groups": [{"position": 1, "keywords": ["ne pas presser", "récit linéaire", "sans exhaustivité forcée"]}]}, {"position": 4, "label": "Contrer par son attitude l''effet de l''argument du conjoint sur sa confiance", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Attitude professionnelle et rassurante restaurant sa confiance.", "groups": [{"position": 1, "keywords": ["contrer l''effet", "confiance restaurée", "attitude rassurante"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment consignez-vous cette situation dans votre procès-verbal, en tenant compte de cette question de l''alcoolisation soulevée par l''auteur ?", "hint": "La manière de formuler le procès-verbal peut soit neutraliser soit involontairement valider cet argument de décrédibilisation.", "perfect": "Je consigne factuellement l''état de consommation d''alcool constaté chez Mme FONTENELLE, sans occulter cette information mais sans non plus lui donner une importance disproportionnée qui suggérerait un lien avec la fiabilité de son récit.\n\nJe rédige mes constatations sur les blessures de manière indépendante de toute mention relative à son état, en présentant ces éléments matériels comme des faits objectifs constatés par moi-même, indépendamment de son état de consommation.\n\nJe consigne également la remarque insistante de M. FONTENELLE sur ce sujet, cet élément pouvant lui-même être révélateur d''une stratégie de défense qui mérite d''être connue par l''autorité qui traitera ce dossier.\n\nJe ne formule à aucun moment mes constatations d''une manière qui laisserait entendre un doute de ma part sur la fiabilité du récit de Mme FONTENELLE du seul fait de son état, cette neutralité rédactionnelle étant essentielle pour ne pas involontairement valider l''argument de décrédibilisation.", "points": [{"position": 1, "label": "Consigner factuellement l''état sans lui donner une importance disproportionnée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Information présente sans suggérer de lien avec la fiabilité.", "groups": [{"position": 1, "keywords": ["consigner factuellement", "sans importance disproportionnée", "sans suggérer de lien"]}]}, {"position": 2, "label": "Rédiger les constatations sur les blessures indépendamment de l''état", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Faits objectifs constatés indépendamment de la consommation.", "groups": [{"position": 1, "keywords": ["constatations indépendantes", "faits objectifs", "indépendant de l''état"]}]}, {"position": 3, "label": "Consigner la remarque insistante du conjoint comme élément révélateur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Stratégie de défense qui mérite d''être connue de l''autorité compétente.", "groups": [{"position": 1, "keywords": ["consigner la remarque", "stratégie de défense", "révélateur"]}]}, {"position": 4, "label": "Ne pas formuler les constatations de manière à suggérer un doute", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Neutralité rédactionnelle pour ne pas valider la décrédibilisation.", "groups": [{"position": 1, "keywords": ["neutralité rédactionnelle", "ne pas valider", "sans suggérer de doute"]}]}]}]}'::jsonb);

-- vif-plainte-par-un-tiers-professionnel-sante — Le médecin a signalé, la patiente n'est pas au courant
SELECT public.fn_cp_import_case('vif-plainte-par-un-tiers-professionnel-sante', '{"slug": "vif-plainte-par-un-tiers-professionnel-sante", "title": "Le médecin a signalé, la patiente n''est pas au courant", "theme_slug": "violences-conjugales", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 14 h 30. Vous recevez un signalement transmis par un médecin généraliste concernant Mme VASSEUR, 42 ans, qu''il a examinée la veille pour des blessures qu''il estime incompatibles avec l''explication donnée par sa patiente d''une chute accidentelle. Le médecin, tenu à ses propres obligations professionnelles, a signalé la situation sans en informer sa patiente, qui ignore donc totalement que cette démarche a été engagée en son nom.\n\nVous devez désormais entrer en contact avec Mme VASSEUR pour donner suite à ce signalement, sans disposer d''aucun élément direct de sa part et sans qu''elle ne soit préparée à cette prise de contact, ce qui pourrait la surprendre voire l''inquiéter si elle ignore le contexte médical à l''origine de votre démarche.\n\nAucune information ne permet de savoir si son conjoint, chez qui elle vit, aura connaissance de cette prise de contact ni comment il pourrait réagir si tel était le cas, ce qui impose une prudence particulière dans la manière d''organiser cette approche.", "questions": [{"position": 1, "max_points": 5, "label": "Comment organisez-vous cette prise de contact initiale avec Mme VASSEUR, qui ignore l''existence du signalement médical ?", "hint": "L''approche doit permettre de vérifier la situation sans la mettre en danger ni la braquer par une intrusion mal préparée.", "perfect": "Je choisis un mode de contact qui ne risque pas d''exposer Mme VASSEUR face à son conjoint si celui-ci était présent, en évitant par exemple un appel téléphonique impromptu au domicile qui pourrait être intercepté ou mal interprété par lui.\n\nJe privilégie une approche qui lui permette de comprendre progressivement le contexte de ma démarche, sans la brusquer avec une révélation abrupte du signalement médical qui pourrait la surprendre douloureusement.\n\nJe reste vigilante à ne pas mentionner explicitement le nom du médecin ou les détails précis de son signalement dans un premier temps, préférant une approche générale qui lui laisse la possibilité de s''exprimer librement sur sa situation.\n\nJe garde à l''esprit que cette prise de contact initiale doit avant tout viser à évaluer si elle est en sécurité pour parler, plutôt que d''obtenir immédiatement des informations détaillées sur ce qui s''est passé.", "points": [{"position": 1, "label": "Choisir un mode de contact ne l''exposant pas face à son conjoint", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : approcher la victime sans la mettre en danger ni la braquer.", "groups": [{"position": 1, "keywords": ["mode de contact sûr", "ne pas exposer", "éviter l''interception"]}]}, {"position": 2, "label": "Permettre une compréhension progressive du contexte sans révélation abrupte", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter de la surprendre douloureusement d''emblée.", "groups": [{"position": 1, "keywords": ["compréhension progressive", "sans révélation abrupte", "éviter la surprise"]}]}, {"position": 3, "label": "Ne pas mentionner explicitement le médecin dans un premier temps", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Approche générale lui laissant la liberté de s''exprimer.", "groups": [{"position": 1, "keywords": ["ne pas mentionner le médecin", "approche générale", "liberté d''expression"]}]}, {"position": 4, "label": "Viser d''abord à évaluer si elle est en sécurité pour parler", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Priorité sur l''obtention immédiate d''informations détaillées.", "groups": [{"position": 1, "keywords": ["évaluer la sécurité pour parler", "avant les détails"]}]}]}, {"position": 2, "max_points": 5, "label": "Une fois le contact établi, comment lui expliquez-vous l''origine de votre démarche sans compromettre la relation qu''elle a avec son médecin ?", "hint": "Il s''agit de trouver un équilibre entre transparence sur l''origine du signalement et préservation de la relation de confiance médicale.", "perfect": "Je lui explique honnêtement qu''un signalement a été effectué par un professionnel de santé concernant des blessures qu''il a jugées incompatibles avec l''explication donnée, sans pour autant dramatiser cette information ni la présenter comme une accusation portée contre elle.\n\nJe la rassure sur le fait que ce signalement s''inscrit dans une obligation professionnelle du médecin visant à la protéger, plutôt que comme une trahison de sa confidentialité médicale qui pourrait détériorer sa relation avec ce praticien.\n\nJe ne cherche pas à recueillir immédiatement des détails précis sur ses blessures ou leurs circonstances si elle semble encore sous le choc de cette révélation, en lui laissant le temps de digérer cette information avant d''aller plus loin.\n\nJe reste attentive à ce qu''elle ne se sente pas prise au piège entre son médecin et moi-même, en présentant cette situation comme la conséquence normale d''un dispositif de protection plutôt que comme une double contrainte pesant sur elle.", "points": [{"position": 1, "label": "Expliquer honnêtement l''origine du signalement sans dramatiser", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Ni accusation, ni dramatisation excessive.", "groups": [{"position": 1, "keywords": ["expliquer honnêtement", "sans dramatiser", "pas une accusation"]}]}, {"position": 2, "label": "La rassurer que le signalement relève d''une obligation protectrice, pas d''une trahison", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Préserver la relation de confiance avec son médecin.", "groups": [{"position": 1, "keywords": ["obligation protectrice", "pas une trahison", "préserver la relation"]}]}, {"position": 3, "label": "Ne pas recueillir immédiatement des détails si elle est sous le choc", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Lui laisser le temps de digérer cette information.", "groups": [{"position": 1, "keywords": ["ne pas presser", "sous le choc", "temps de digérer"]}]}, {"position": 4, "label": "Éviter qu''elle se sente prise au piège entre le médecin et la police", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Présenter la situation comme un dispositif de protection cohérent.", "groups": [{"position": 1, "keywords": ["pas prise au piège", "dispositif de protection", "cohérent"]}]}]}, {"position": 3, "max_points": 5, "label": "Elle nie finalement toute violence et maintient sa version de la chute accidentelle. Comment concluez-vous cette intervention ?", "hint": "Un déni de sa part ne clôt pas nécessairement la question, compte tenu du contexte médical qui a motivé l''alerte initiale.", "perfect": "Je ne la force pas à admettre des faits qu''elle nie, respectant sa parole actuelle tout en gardant à l''esprit que ce déni peut être lié à la peur ou à d''autres facteurs que je ne maîtrise pas à cet instant.\n\nJe consigne fidèlement sa version des faits telle qu''elle me la présente, sans la qualifier de mensongère mais sans non plus effacer l''origine médicale du signalement qui a motivé mon intervention.\n\nJe lui laisse, avant de partir, des informations discrètes sur les dispositifs d''aide existants, qu''elle pourra utiliser à sa propre initiative si sa situation venait à évoluer différemment de ce qu''elle affirme aujourd''hui.\n\nJe transmets un compte rendu complet de cette intervention, incluant le signalement médical initial et le déni actuel de l''intéressée, ce qui permettra une appréciation éclairée si de nouveaux éléments devaient survenir ultérieurement.", "points": [{"position": 1, "label": "Ne pas la forcer à admettre des faits qu''elle nie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Respecter sa parole actuelle tout en restant consciente des facteurs possibles.", "groups": [{"position": 1, "keywords": ["ne pas forcer", "respecter sa parole", "facteurs possibles"]}]}, {"position": 2, "label": "Consigner fidèlement sa version sans la qualifier de mensongère", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans effacer l''origine médicale du signalement.", "groups": [{"position": 1, "keywords": ["consigner fidèlement", "sans qualifier de mensonge", "origine médicale conservée"]}]}, {"position": 3, "label": "Laisser discrètement des informations sur les dispositifs d''aide", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Utilisables à son initiative si la situation évolue.", "groups": [{"position": 1, "keywords": ["informations discrètes", "dispositifs d''aide", "à son initiative"]}]}, {"position": 4, "label": "Transmettre un compte rendu complet incluant le signalement et le déni", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Appréciation éclairée en cas de nouveaux éléments futurs.", "groups": [{"position": 1, "keywords": ["compte rendu complet", "appréciation future", "nouveaux éléments"]}]}]}]}'::jsonb);

-- vif-menaces-par-la-famille-de-l-auteur — Depuis la plainte, c'est la belle-famille qui l'attend en bas
SELECT public.fn_cp_import_case('vif-menaces-par-la-famille-de-l-auteur', '{"slug": "vif-menaces-par-la-famille-de-l-auteur", "title": "Depuis la plainte, c''est la belle-famille qui l''attend en bas", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 17 heures. Mme TORRES, ayant déposé plainte deux semaines plus tôt contre son conjoint pour des violences conjugales, vous contacte de nouveau, cette fois pour signaler que ce n''est plus son conjoint qui la menace directement, mais des membres de sa belle-famille, notamment son beau-frère et sa belle-mère, qui l''attendent régulièrement en bas de son immeuble depuis le dépôt de sa plainte, lui adressant des regards insistants et des remarques désobligeantes sur le fait d''avoir « détruit la famille ».\n\nElle précise qu''aucun de ces membres de la belle-famille n''a jamais été mentionné dans sa plainte initiale, qui ne concernait que son conjoint, et qu''elle ne sait pas comment qualifier ce qu''elle vit maintenant, ce harcèlement de la part de tiers extérieurs au couple lui semblant différent de ce qu''elle a déjà signalé.\n\nElle exprime une peur grandissante de sortir de chez elle, cette pression collective de la belle-famille s''ajoutant à l''angoisse déjà présente liée à la procédure en cours contre son conjoint.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous cette nouvelle situation impliquant des membres de la belle-famille plutôt que le conjoint lui-même ?", "hint": "Le danger ne se limite pas toujours à l''auteur initial des violences conjugales ; il peut s''étendre à son entourage proche.", "perfect": "Je reconnais que ce risque d''élargissement du danger au-delà de l''auteur initial constitue un phénomène connu dans les suites de plaintes pour violences conjugales, l''entourage de l''auteur pouvant exercer une pression collective distincte mais tout aussi réelle.\n\nJe prends en compte l''entourage de M. TORRES comme un facteur de risque à part entière, ce type de pression indirecte pouvant avoir des conséquences tout aussi graves qu''une menace directe de la part de l''auteur lui-même.\n\nJe recueille avec précision les circonstances de ces rencontres répétées, notamment leur fréquence, les propos exacts tenus, et l''identification précise des personnes impliquées, ce qui permettra de qualifier juridiquement ces faits nouveaux.\n\nJe ne minimise pas cette situation au prétexte qu''elle diffère de ce qui a été initialement signalé contre le conjoint, ce nouveau volet méritant un traitement à part entière plutôt qu''un simple ajout mineur au dossier existant.", "points": [{"position": 1, "label": "Reconnaître le phénomène d''élargissement du danger à l''entourage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : prendre en compte l''entourage comme facteur de risque.", "groups": [{"position": 1, "keywords": ["élargissement du danger", "entourage", "phénomène connu"]}]}, {"position": 2, "label": "Prendre en compte l''entourage comme facteur de risque à part entière", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pression indirecte aussi grave qu''une menace directe.", "groups": [{"position": 1, "keywords": ["facteur de risque", "pression indirecte", "aussi grave"]}]}, {"position": 3, "label": "Recueillir précisément les circonstances des rencontres répétées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Fréquence, propos exacts, identification des personnes impliquées.", "groups": [{"position": 1, "keywords": ["circonstances précises", "fréquence", "identification des personnes"]}]}, {"position": 4, "label": "Ne pas minimiser ce nouveau volet distinct de la plainte initiale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Traitement à part entière plutôt qu''un simple ajout mineur.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "volet distinct", "traitement à part entière"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment organisez-vous concrètement la protection de Mme TORRES face à cette pression exercée par sa belle-famille ?", "hint": "Les mesures de protection existantes doivent être adaptées pour couvrir ce nouveau périmètre de risque élargi à l''entourage.", "perfect": "Je vérifie si les mesures de protection déjà en place dans le cadre de la plainte initiale contre son conjoint pourraient être étendues ou complétées pour prendre en compte cette pression exercée par les membres de sa belle-famille.\n\nJe l''informe des possibilités de signalement spécifique de ces nouveaux faits, qui constituent des infractions potentiellement distinctes de celles déjà signalées contre son conjoint, ce qui nécessite une démarche complémentaire de sa part si elle le souhaite.\n\nJe recommande des mesures pratiques immédiates pour limiter son exposition à ces rencontres, comme varier ses horaires ou trajets habituels le temps que la situation soit clarifiée par les autorités compétentes.\n\nJe reste attentive à son état d''angoisse grandissant, qui s''ajoute à celui déjà lié à la procédure contre son conjoint, en m''assurant qu''elle dispose d''un accompagnement suffisant pour faire face à cette pression cumulée.", "points": [{"position": 1, "label": "Vérifier si les mesures de protection existantes peuvent être étendues", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Adapter le périmètre de risque élargi à l''entourage.", "groups": [{"position": 1, "keywords": ["mesures étendues", "périmètre élargi", "compléter la protection"]}]}, {"position": 2, "label": "Informer des possibilités de signalement spécifique de ces nouveaux faits", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Infractions potentiellement distinctes nécessitant une démarche complémentaire.", "groups": [{"position": 1, "keywords": ["signalement spécifique", "infractions distinctes", "démarche complémentaire"]}]}, {"position": 3, "label": "Recommander des mesures pratiques immédiates pour limiter l''exposition", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Varier horaires et trajets en attendant la clarification.", "groups": [{"position": 1, "keywords": ["mesures pratiques", "varier les trajets", "limiter l''exposition"]}]}, {"position": 4, "label": "Rester attentive à son état d''angoisse cumulée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "S''assurer d''un accompagnement suffisant face à la pression multiple.", "groups": [{"position": 1, "keywords": ["angoisse cumulée", "accompagnement suffisant", "pression multiple"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment cette nouvelle information doit-elle être articulée avec le dossier judiciaire déjà en cours contre M. TORRES ?", "hint": "La coordination entre ce nouveau signalement et la procédure existante est essentielle pour une vision globale du risque.", "perfect": "Je m''assure que cette nouvelle information soit clairement rattachée au dossier existant contre M. TORRES, plutôt que d''être traitée comme un signalement isolé et déconnecté de la procédure en cours.\n\nJe transmets ces éléments à l''autorité en charge du dossier initial, ce lien entre les deux affaires pouvant être pertinent pour l''appréciation globale du risque que représente cette situation familiale pour Mme TORRES.\n\nJe consigne avec précision cette possible instrumentalisation de l''entourage familial, qui pourrait, selon les circonstances, constituer une forme de pression organisée visant à influencer l''issue de la procédure judiciaire en cours.\n\nJe reste attentive à ne pas préjuger d''une coordination entre M. TORRES et sa famille dans cette pression, cette question devant être établie par l''enquête plutôt que présumée sur la seule base de la coïncidence temporelle avec la plainte.", "points": [{"position": 1, "label": "Rattacher clairement cette information au dossier existant", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Éviter un traitement isolé et déconnecté de la procédure en cours.", "groups": [{"position": 1, "keywords": ["rattacher au dossier", "pas isolé", "procédure en cours"]}]}, {"position": 2, "label": "Transmettre à l''autorité en charge du dossier initial", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pertinent pour l''appréciation globale du risque.", "groups": [{"position": 1, "keywords": ["transmettre à l''autorité", "appréciation globale", "risque global"]}]}, {"position": 3, "label": "Consigner la possible instrumentalisation de l''entourage familial", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Forme de pression organisée visant à influencer la procédure.", "groups": [{"position": 1, "keywords": ["instrumentalisation", "pression organisée", "influencer la procédure"]}]}, {"position": 4, "label": "Ne pas préjuger d''une coordination sans preuve établie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Question à établir par l''enquête plutôt que présumer.", "groups": [{"position": 1, "keywords": ["ne pas préjuger", "établir par l''enquête", "pas de présomption"]}]}]}]}'::jsonb);

