SELECT public.fn_cp_import_case('vif-retour-au-domicile-apres-eviction', '{"slug": "vif-retour-au-domicile-apres-eviction", "title": "Il est revenu récupérer ses affaires, elle a ouvert", "theme_slug": "violences-conjugales", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 1 h 15. Vous êtes engagés dans un pavillon suite à un signalement de voisinage, un voisin ayant reconnu la voiture de M. DELAGE garée devant le domicile de son ex-compagne alors qu''une mesure d''éviction lui interdit formellement de s''y présenter depuis une intervention survenue dix jours plus tôt. À votre arrivée, Mme BOUCHARD vous ouvre elle-même la porte, expliquant que M. DELAGE est venu récupérer quelques affaires personnelles et qu''elle avait « accepté » cette visite exceptionnelle.\n\nElle insiste sur le fait que tout s''est bien passé, qu''elle l''a elle-même invité à entrer pour cette occasion précise, et qu''elle ne comprend pas pourquoi vous interviendriez alors qu''elle-même a consenti à cette venue ponctuelle qu''elle présente comme sans conséquence.\n\nM. DELAGE, présent dans le salon avec un sac contenant quelques vêtements, confirme cette version et semble surpris que son ex-compagne ait pu être inquiétée pour un geste qu''elle a elle-même autorisé selon eux deux.", "questions": [{"position": 1, "max_points": 5, "label": "Le consentement apparent de Mme BOUCHARD à cette visite change-t-il la qualification de cette violation de la mesure d''éviction ?", "hint": "Une mesure d''éviction protège un équilibre que le consentement ponctuel de la victime, aussi sincère soit-il, ne peut pas suspendre unilatéralement.", "perfect": "Je considère que ce consentement apparent, aussi sincère puisse-t-il paraître dans l''instant, ne suspend en rien la mesure d''éviction en vigueur, cette dernière relevant d''une décision de l''autorité compétente et non d''un accord informel entre les deux parties.\n\nJe reste attentive au fait que ce type de consentement peut lui-même résulter d''une pression, explicite ou plus subtile, exercée par M. DELAGE pour obtenir cette visite, sans que cela soit nécessairement perceptible immédiatement dans le discours de Mme BOUCHARD.\n\nJe ne me positionne pas comme validant cette exception qu''ils ont eux-mêmes décidée entre eux, en expliquant clairement que la mesure d''éviction ne peut être levée que par l''autorité qui l''a prononcée, et non par un accord bilatéral entre les intéressés.\n\nJe considère que cette violation de la mesure doit être traitée comme telle, indépendamment du fait que Mme BOUCHARD ait elle-même ouvert la porte, cette question de consentement ne modifiant pas la réalité juridique de l''infraction constatée.", "points": [{"position": 1, "label": "Considérer que le consentement ne suspend pas la mesure d''éviction", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : faire respecter la mesure malgré l''accord apparent.", "groups": [{"position": 1, "keywords": ["consentement ne suspend pas", "mesure en vigueur", "autorité compétente"]}]}, {"position": 2, "label": "Rester attentive au fait que ce consentement peut résulter d''une pression", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pression subtile pas nécessairement perceptible immédiatement.", "groups": [{"position": 1, "keywords": ["pression possible", "pas perceptible immédiatement", "vigilance"]}]}, {"position": 3, "label": "Ne pas valider l''exception décidée entre les deux parties", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Seule l''autorité qui a prononcé la mesure peut la lever.", "groups": [{"position": 1, "keywords": ["ne pas valider l''exception", "seule l''autorité", "lever la mesure"]}]}, {"position": 4, "label": "Traiter la violation comme telle indépendamment de l''ouverture de la porte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Le consentement ne modifie pas la réalité juridique de l''infraction.", "groups": [{"position": 1, "keywords": ["violation constatée", "réalité juridique", "indépendant du consentement"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous concrètement la situation avec les deux personnes présentes, qui semblent toutes deux surprises de votre intervention ?", "hint": "Leur surprise commune ne doit pas vous conduire à minimiser la gravité de la violation constatée.", "perfect": "Je constate la présence de M. DELAGE en violation de la mesure d''éviction, en procédant aux constatations nécessaires indépendamment de la surprise exprimée par les deux personnes présentes.\n\nJe fais quitter les lieux à M. DELAGE sans délai, cette mesure restant applicable quelle que soit l''explication donnée sur les circonstances de sa présence ce soir.\n\nJe prends le temps d''expliquer à Mme BOUCHARD, sans la culpabiliser pour son geste d''ouverture de la porte, pourquoi cette mesure existe précisément pour la protéger indépendamment de sa propre appréciation du moment sur la situation.\n\nJe reste attentive à ne pas la traiter comme complice d''une infraction, son statut de victime protégée par cette mesure restant central, même si son propre comportement a facilité cette violation.", "points": [{"position": 1, "label": "Constater la violation et procéder aux constatations nécessaires", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Indépendamment de la surprise exprimée par les deux personnes.", "groups": [{"position": 1, "keywords": ["constater la violation", "constatations nécessaires", "indépendant de la surprise"]}]}, {"position": 2, "label": "Faire quitter les lieux à M. DELAGE sans délai", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Mesure applicable quelle que soit l''explication donnée.", "groups": [{"position": 1, "keywords": ["faire quitter sans délai", "applicable quelle que soit l''explication"]}]}, {"position": 3, "label": "Expliquer à Mme BOUCHARD sans la culpabiliser pourquoi la mesure existe", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Protection indépendante de sa propre appréciation du moment.", "groups": [{"position": 1, "keywords": ["expliquer sans culpabiliser", "protection", "indépendant de son appréciation"]}]}, {"position": 4, "label": "Ne pas la traiter comme complice de l''infraction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Son statut de victime protégée reste central.", "groups": [{"position": 1, "keywords": ["pas complice", "victime protégée", "statut central"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment consignez-vous cette intervention pour la suite de la procédure judiciaire concernant M. DELAGE ?", "hint": "Cette violation, même consentie apparemment, constitue un élément à part entière du dossier judiciaire en cours.", "perfect": "Je consigne avec précision cette violation constatée de la mesure d''éviction, en incluant l''ensemble des circonstances, notamment le consentement apparent de Mme BOUCHARD et les explications données par les deux parties.\n\nJe transmets ce constat à l''autorité judiciaire en charge du dossier initial, cette violation constituant potentiellement un élément aggravant ou du moins significatif dans l''appréciation du respect par M. DELAGE des mesures qui lui sont imposées.\n\nJe ne minimise pas cette violation dans ma rédaction sous prétexte du contexte apparemment consenti, en présentant les faits de manière factuelle sans que ma formulation ne suggère une atténuation de leur gravité.\n\nJe reste attentive à documenter également l''état de Mme BOUCHARD lors de cette intervention, ce qui pourrait éclairer utilement la question de savoir si son consentement était réellement libre ou influencé par la dynamique de leur relation passée.", "points": [{"position": 1, "label": "Consigner précisément la violation avec l''ensemble des circonstances", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Consentement apparent et explications des deux parties incluses.", "groups": [{"position": 1, "keywords": ["consigner précisément", "circonstances complètes", "consentement apparent"]}]}, {"position": 2, "label": "Transmettre ce constat à l''autorité judiciaire en charge du dossier", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Élément significatif dans l''appréciation du respect des mesures.", "groups": [{"position": 1, "keywords": ["transmettre à l''autorité", "élément significatif", "respect des mesures"]}]}, {"position": 3, "label": "Ne pas minimiser la violation dans la rédaction du constat", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Formulation factuelle sans atténuation de la gravité.", "groups": [{"position": 1, "keywords": ["ne pas minimiser", "formulation factuelle", "sans atténuation"]}]}, {"position": 4, "label": "Documenter l''état de la victime pour éclairer la liberté de son consentement", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Consentement réellement libre ou influencé par la relation passée.", "groups": [{"position": 1, "keywords": ["documenter l''état", "consentement libre ou influencé", "dynamique relationnelle"]}]}]}]}'::jsonb);

